#include "dual_loss_parallel.cuh"
#include <cstdio>
int main(){try{using namespace tao::dual;float worst=0;for(int n:{261,513,16384})for(float mult:{0.f,.5f,1.f}){Vec x(n),g(n,.125f);for(int j=0;j<n;++j)x[j]=float((j*37)%199-99)*.7f;Device dx(x),a(g),b(g),la(1),lb(1);int target=n-3;ds_cross_entropy<<<1,1>>>(dx.p,a.p,la.p,n,target,mult);ds_ce_parallel<<<1,256>>>(dx.p,b.p,lb.p,n,target,mult);auto ga=a.host(),gb=b.host();float le=fabsf(la.host()[0]-lb.host()[0]);if(le>3e-5f)throw std::runtime_error("loss mismatch");for(int j=0;j<n;++j){float e=fabsf(ga[j]-gb[j]);worst=fmaxf(worst,e);if(e>3e-6f)throw std::runtime_error("gradient mismatch");}}printf("PASS parallel CE 9 cases sizes261/513/16384 multipliers0/.5/1 additive gradients maxerror=%.9g\n",worst);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
